"""Replaces the duplicate lunar excursion while retaining map/topic IDs 35/70/71."""
URL='https://www.iaea.org/sites/default/files/21/04/iaea-background-document-chornobyl.pdf'
ACCIDENT_URL='https://www.chnpp.gov.ua/en/about/history-of-the-chnpp/accident-of-1986'
def apply(Stage,Lesson,stages,lessons,sources):
    stages[35]=Stage('Chernóbil · comunicar para proteger','1986: accidente nuclear, evacuación e información pública.','chernobyl')
    source=len(sources);sources.append(('OIEA · Estudios y cooperación sobre Chernóbil',URL))
    accident_source=len(sources);sources.append(('Central de Chornóbil · Accidente de 1986',ACCIDENT_URL))
    rows=(('El accidente de 1986','El 26 de abril de 1986 ocurrió un accidente en el reactor 4 de la central de Chernóbil, en la entonces Unión Soviética, hoy Ucrania. Una prueba derivó en explosiones e incendio y se liberó material radiactivo.',
     ('¿En qué año ocurrió el accidente de Chernóbil?','1986','1969','1816'),('¿Qué tipo de instalación sufrió el accidente?','Una central nuclear','Una biblioteca antigua','Una estación ferroviaria'),('¿Qué reactor se accidentó?','El reactor 4','El módulo Eagle','La locomotora Rocket'),('¿Qué fecha corresponde al accidente?','26 de abril de 1986','20 de julio de 1969','11 de noviembre de 1918'),('¿En qué país actual se encuentra la central?','Ucrania','Brasil','Francia'),('¿Qué se liberó al ambiente?','Material radiactivo','Solo vapor de agua sin otros materiales','Papiro antiguo')),
     ('La información y la protección','El accidente de Chernóbil obligó a evacuar poblaciones, controlar alimentos y estudiar consecuencias ambientales y sanitarias. La cooperación internacional y la comunicación pública fueron importantes para evaluar lo sucedido y mejorar la seguridad nuclear.',
     ('¿Qué medida debieron tomar poblaciones cercanas?','Evacuar zonas afectadas','Visitar el reactor sin protección','Ignorar toda información'),('¿Qué institución internacional estudia la seguridad nuclear?','El OIEA','El Congreso de Tucumán','El santuario de Olimpia'),('¿Por qué se controlaron alimentos y agua?','Para evaluar contaminación radiactiva','Para cambiar el calendario','Para fabricar tinta'),('¿Qué ayudó a investigar las consecuencias del accidente?','La cooperación y las mediciones','Un rumor sin comprobar','Suponer que no ocurrió nada'),('¿Qué diferencia hay entre accidente y bombardeo?','El accidente de Chernóbil no fue un ataque aéreo','Son siempre la misma causa','Chernóbil fue una batalla de 1916'),('¿Qué permite la información pública contrastada?','Conocer riesgos y decisiones de protección','Reemplazar todas las mediciones por opiniones','Volver innecesaria la seguridad')))
    for i,(title,fact,*questions) in enumerate(rows):lessons[70+i]=Lesson(title,fact,accident_source if i==0 else source,tuple(questions))
